125	/** Calcula os intervalos semanais (buckets de 7 dias) de start até end (inclusive). */
126	export function computeWeekRanges(start: Date, end: Date): WeekRange[] {
127	  const ranges: WeekRange[] = [];
128	  let cursor = new Date(start);
129	  let index = 1;
130	
131	  while (cursor <= end) {
132	    const bs = new Date(cursor);
133	    const be = new Date(Math.min(addDays(cursor, 6).getTime(), end.getTime()));
134	
135	    const startFmt = format(bs, 'dd/MM', { locale: ptBR });
136	    const endFmt = format(be, 'dd/MM/yyyy', { locale: ptBR });
137	    const trendSubLabel = `${format(bs, 'dd', { locale: ptBR })}-${format(be, 'dd/MM', { locale: ptBR })}`;
138	
139	    ranges.push({
140	      index,
141	      label: `Semana ${index} — ${startFmt} a ${endFmt}`,
142	      trendLabel: `S${index}`,
143	      trendSubLabel,
144	      start: bs,
145	      end: be,
146	    });
147	
148	    cursor = addDays(be, 1);
149	    index++;
150	  }
151	
152	  return ranges;
153	}
154	
155	/** Divide entries em buckets de 7 dias a partir de start até end (inclusive). */
156	export function splitIntoWeeks(
157	  entries: PerdasEntry[],
158	  start: Date,
159	  end: Date,
160	): WeekBucket[] {
161	  return computeWeekRanges(start, end).map(range => {
162	    const bucketStart = new Date(range.start);
163	    bucketStart.setHours(0, 0, 0, 0);
164	    const bucketEnd = new Date(range.end);
165	    bucketEnd.setHours(23, 59, 59, 999);
166	
167	    const bucketEntries = entries.filter(e => {
168	      if (!e.date) return false;
169	      const d = new Date(e.date);
170	      return d >= bucketStart && d <= bucketEnd;
171	    });
172	
173	    return {
174	      index: range.index,
175	      label: range.label,
176	      trendLabel: range.trendLabel,
177	      trendSubLabel: range.trendSubLabel,
178	      start: range.start,
179	      end: range.end,
180	      entries: bucketEntries,
181	      aggregate: aggregatePerdas(bucketEntries),
182	    };
183	  });
184	}
