211	/**
212	 * Garante espaço vertical suficiente. Se não couber, vira página e retorna 52.
213	 */
214	function ensureSpace(
215	  doc: jsPDF,
216	  cursorY: number,
217	  neededMm: number,
218	  pageHeight: number,
219	  drawPageExtras: (hookData: { pageNumber?: number }) => void,
220	): number {
