229	/**
230	 * Desenha barras horizontais para uma lista de itens.
231	 * Retorna o Y após o último elemento.
232	 */
233	function drawHorizontalBars(
234	  doc: jsPDF,
235	  items: Array<{ label: string; value: number; displayValue: string }>,
236	  x: number,
237	  y: number,
238	  totalWidth: number,
239	  barHeight = 4.5,
240	  gap = 2.5,
241	  barColor: [number, number, number] = MOMMA_GREEN,
242	): number {
243	  if (items.length === 0) return y;
244	
245	  const maxVal = Math.max(...items.map(i => i.value), 1);
246	  const labelWidth = 30;
247	  const valueWidth = 22;
248	  const barAreaWidth = totalWidth - labelWidth - valueWidth;
249	  let curY = y;
250	
251	  for (const item of items) {
252	    // Label (max 15 chars)
253	    const labelTxt = item.label.length > 15 ? item.label.substring(0, 14) + '…' : item.label;
254	    doc.setFont('helvetica', 'normal');
255	    doc.setFontSize(7);
256	    doc.setTextColor(80, 80, 80);
257	    doc.text(labelTxt, x, curY + barHeight - 1);
258	
259	    const barX = x + labelWidth;
260	
261	    // Background bar
262	    doc.setFillColor(235, 235, 235);
263	    doc.rect(barX, curY, barAreaWidth, barHeight, 'F');
264	
265	    // Colored bar (proportional)
266	    if (item.value > 0) {
267	      const filledW = Math.max(1, (item.value / maxVal) * barAreaWidth);
268	      doc.setFillColor(...barColor);
269	      doc.rect(barX, curY, filledW, barHeight, 'F');
270	    }
271	
272	    // Value label (right)
273	    doc.setFont('helvetica', 'bold');
274	    doc.setFontSize(7);
275	    doc.setTextColor(...MOMMA_GREEN_DARK);
276	    doc.text(item.displayValue, x + totalWidth, curY + barHeight - 1, { align: 'right' });
277	
278	    curY += barHeight + gap;
279	  }
280	
281	  return curY;
282	}
