284	/**
285	 * Desenha barras verticais para dados de tendência.
286	 */
287	function drawVerticalBars(
288	  doc: jsPDF,
289	  items: Array<{ trendLabel: string; trendSubLabel: string; value: number; displayValue: string }>,
290	  x: number,
291	  y: number,
292	  chartWidth: number,
293	  chartHeight: number,
294	  barColor: [number, number, number] = MOMMA_GREEN,
295	): void {
296	  if (items.length === 0) return;
297	
298	  const hasData = items.some(i => i.value > 0);
299	  if (!hasData) return;
300	
301	  const maxVal = Math.max(...items.map(i => i.value), 1);
302	  const n = items.length;
303	  const slotW = chartWidth / n;
304	  const barW = slotW * 0.6;
305	  const axisLabelH = 12; // height reserved below chart for labels
306	  const drawH = chartHeight - axisLabelH;
307	
308	  // Baseline
309	  doc.setDrawColor(200, 200, 200);
310	  doc.setLineWidth(0.3);
311	  doc.line(x, y + drawH, x + chartWidth, y + drawH);
312	
313	  for (let i = 0; i < items.length; i++) {
314	    const item = items[i];
315	    const slotX = x + i * slotW;
316	    const barX = slotX + (slotW - barW) / 2;
317	    const barH = item.value > 0 ? Math.max(1, (item.value / maxVal) * drawH) : 0;
318	    const barY = y + drawH - barH;
319	
320	    // Draw bar
321	    if (barH > 0) {
322	      doc.setFillColor(...barColor);
323	      doc.rect(barX, barY, barW, barH, 'F');
324	    }
325	
326	    // Value label above bar (only if bar is tall enough)
327	    if (barH > 6) {
328	      doc.setFont('helvetica', 'bold');
329	      doc.setFontSize(6);
330	      doc.setTextColor(...MOMMA_GREEN_DARK);
331	      doc.text(item.displayValue, barX + barW / 2, barY - 1, { align: 'center' });
332	    }
333	
334	    // Axis labels below baseline
335	    const labelCenterX = slotX + slotW / 2;
336	    doc.setFont('helvetica', 'bold');
337	    doc.setFontSize(7);
338	    doc.setTextColor(80, 80, 80);
339	    doc.text(item.trendLabel, labelCenterX, y + drawH + 5, { align: 'center' });
340	
341	    doc.setFont('helvetica', 'normal');
342	    doc.setFontSize(6);
343	    doc.setTextColor(120, 120, 120);
344	    doc.text(item.trendSubLabel, labelCenterX, y + drawH + 10, { align: 'center' });
345	  }
346	}
