647	    const end = new Date(dateEnd + 'T00:00:00');
648	    const diffDays = Math.round((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1;
649	
650	    // Agrupamento: por dia se ≤60, por semana se >60
651	    const byDayMap = new Map<string, number>();
652	
653	    if (diffDays <= 60) {
654	      for (const e of entries) {
655	        if (!e.date) continue;
656	        const dayKey = e.date.substring(0, 10);
657	        byDayMap.set(dayKey, (byDayMap.get(dayKey) ?? 0) + e.val);
658	      }
