895	export interface GeralAggregate {
896	  totalValue: number;
897	  totalRecords: number;
898	  storeCount: number;           // lojas distintas com value > 0
899	  lojaCritica: string;          // loja de maior valor ("-" se vazio)
900	  concentracao: number;         // pct da loja crítica
901	  byStore: GeralStoreRow[];     // ordenado por value desc
902	}
