904	// ───────────────────────── HELPER PURO (TESTÁVEL) ─────────────────────────
905	
906	export function aggregateGeral(entries: PerdasGeralEntry[]): GeralAggregate {
907	  if (entries.length === 0) {
908	    return {
909	      totalValue: 0,
910	      totalRecords: 0,
911	      storeCount: 0,
912	      lojaCritica: '-',
913	      concentracao: 0,
914	      byStore: [],
915	    };
916	  }
917	
918	  const totalValue = entries.reduce((s, e) => s + e.val, 0);
919	  const totalRecords = entries.length;
920	
921	  const storeMap = new Map<string, { value: number; count: number }>();
922	  for (const e of entries) {
923	    const name = e.store && e.store.trim() ? e.store : 'Sem loja';
924	    const cur = storeMap.get(name) ?? { value: 0, count: 0 };
925	    storeMap.set(name, { value: cur.value + e.val, count: cur.count + 1 });
926	  }
927	
928	  const byStore: GeralStoreRow[] = Array.from(storeMap.entries())
929	    .map(([store, d]) => ({
930	      store,
931	      value: d.value,
932	      count: d.count,
933	      pct: totalValue > 0 ? (d.value / totalValue) * 100 : 0,
934	    }))
935	    .sort((a, b) => b.value - a.value);
936	
937	  const storeCount = byStore.filter(s => s.value > 0).length;
938	  const lojaCritica = byStore.length > 0 ? byStore[0].store : '-';
939	  const concentracao = byStore.length > 0 ? byStore[0].pct : 0;
940	
941	  return {
942	    totalValue,
943	    totalRecords,
944	    storeCount,
945	    lojaCritica,
946	    concentracao,
947	    byStore,
948	  };
949	}
