951	/** Filtra entries cujo `date` cai dentro do range [start, end] (dia inteiro). */
952	function entriesInRange(entries: PerdasGeralEntry[], start: Date, end: Date): PerdasGeralEntry[] {
953	  const s = new Date(start); s.setHours(0, 0, 0, 0);
954	  const e = new Date(end); e.setHours(23, 59, 59, 999);
955	  return entries.filter(en => {
956	    if (!en.date) return false;
957	    const d = new Date(en.date);
958	    return d >= s && d <= e;
959	  });
960	}
