964	/**
965	 * Desenha barras horizontais comparando lojas (valor + % dentro da barra).
966	 * Retorna o Y após o último item.
967	 */
968	function drawStoreBars(
969	  doc: jsPDF,
970	  items: Array<{ store: string; value: number; pct: number }>,
971	  x: number,
972	  y: number,
973	  totalWidth: number,
974	  barHeight = 5.5,
975	  gap = 3,
976	): number {
977	  if (items.length === 0) return y;
978	
979	  const maxVal = Math.max(...items.map(i => i.value), 1);
980	  const labelWidth = 40;
981	  const valueWidth = 28;
982	  const barArea = totalWidth - labelWidth - valueWidth;
983	  let curY = y;
984	
985	  for (const item of items) {
986	    // Label (nome da loja, max 22 chars)
987	    const labelTxt = item.store.length > 22 ? item.store.substring(0, 21) + '…' : item.store;
988	    doc.setFont('helvetica', 'normal');
989	    doc.setFontSize(7.5);
990	    doc.setTextColor(70, 70, 70);
991	    doc.text(labelTxt, x, curY + barHeight - 1.5);
992	
993	    const barX = x + labelWidth;
994	
995	    // Background bar
996	    doc.setFillColor(235, 235, 235);
997	    doc.rect(barX, curY, barArea, barHeight, 'F');
998	
999	    if (item.value > 0) {
1000	      const filledW = Math.max(1, (item.value / maxVal) * barArea);
1001	      doc.setFillColor(...MOMMA_GREEN);
1002	      doc.rect(barX, curY, filledW, barHeight, 'F');
1003	
1004	      const pctTxt = pctFmt(item.pct);
1005	      if (filledW >= 14) {
1006	        // % dentro da barra, branco, centralizado
1007	        doc.setFont('helvetica', 'bold');
1008	        doc.setFontSize(7);
1009	        doc.setTextColor(255, 255, 255);
1010	        doc.text(pctTxt, barX + filledW / 2, curY + barHeight / 2 + 1, { align: 'center' });
1011	      } else {
1012	        // % logo após a barra preenchida
1013	        doc.setFont('helvetica', 'normal');
1014	        doc.setFontSize(7);
1015	        doc.setTextColor(...MOMMA_GREEN_DARK);
1016	        doc.text(pctTxt, barX + filledW + 1.5, curY + barHeight - 1.5);
1017	      }
1018	    }
1019	
1020	    // Valor R$ à direita
1021	    doc.setFont('helvetica', 'bold');
1022	    doc.setFontSize(7.5);
1023	    doc.setTextColor(...MOMMA_GREEN_DARK);
1024	    doc.text(currencyFmt(item.value), x + totalWidth, curY + barHeight - 1.5, { align: 'right' });
1025	
1026	    curY += barHeight + gap;
1027	  }
1028	
1029	  return curY;
1030	}
