const noneSelected = selectedStoreIds.has(-1);
const allStoresSelected = !noneSelected && (selectedStoreIds.size === 0 || selectedStoreIds.size === stores.length);
const isStoreIncluded = (lojaId: number | null | undefined): boolean => {
    if (noneSelected) return false;
    return selectedStoreIds.size === 0 || (lojaId != null && selectedStoreIds.has(lojaId));
};

const toggleStore = (id: number) => {
    setSelectedStoreIds(prev => {
        const next = new Set(prev);
        // Sentinel "nenhuma" — começar de um Set vazio antes de adicionar a clicada.
        if (next.has(-1)) next.clear();
        // Se estava vazio (=todas), começar a partir de todas e remover a clicada.
        if (next.size === 0) { stores.forEach(s => next.add(s.id)); }
        if (next.has(id)) next.delete(id); else next.add(id);
        // Se voltou a ter todas, normaliza pra vazio (=todas).
        if (next.size === stores.length) return new Set<number>();
        return next;
    });
};

