export function aggregateGeral(entries: PerdasGeralEntry[]): GeralAggregate {
  if (entries.length === 0) {
    return {
      totalValue: 0,
      totalRecords: 0,
      storeCount: 0,
      lojaCritica: '-',
      concentracao: 0,
      byStore: [],
    };
  }

  const totalValue = entries.reduce((s, e) => s + e.val, 0);
  const totalRecords = entries.length;

  const storeMap = new Map<string, { value: number; count: number }>();
  for (const e of entries) {
    const name = e.store && e.store.trim() ? e.store : 'Sem loja';
    const cur = storeMap.get(name) ?? { value: 0, count: 0 };
    storeMap.set(name, { value: cur.value + e.val, count: cur.count + 1 });
  }

  const byStore: GeralStoreRow[] = Array.from(storeMap.entries())
    .map(([store, d]) => ({
      store,
      value: d.value,
      count: d.count,
      pct: totalValue > 0 ? (d.value / totalValue) * 100 : 0,
    }))
    .sort((a, b) => b.value - a.value);

  const storeCount = byStore.filter(s => s.value > 0).length;
  const lojaCritica = byStore.length > 0 ? byStore[0].store : '-';
  const concentracao = byStore.length > 0 ? byStore[0].pct : 0;

  return {
    totalValue,
    totalRecords,
    storeCount,
    lojaCritica,
    concentracao,
    byStore,
  };
}

